func newShadowSettings() unsafe.Pointer { return unsafe.Pointer(new(extractionshadow.ShadowSettings)) }

func newNShadowSettings(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]extractionshadow.ShadowSettings, n)))
}

func ptrShadowSettings(p unsafe.Pointer, c int32) any {
	r := (*extractionshadow.ShadowSettings)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Enabled
	case 4:
		return (**string)(unsafe.Pointer(&r.ProviderID))
	case 5:
		return (*int64)(unsafe.Pointer(&r.SamplePercent))
	case 6:
		return (*int64)(unsafe.Pointer(&r.DailyLimit))
	case 7:
		return (**string)(unsafe.Pointer(&r.UpdatedByID))
	case 8:
		return &r.Version
	case 9:
		return &r.CreatedAt
	case 10:
		return &r.UpdatedAt
	}
	return nil
}

func valueShadowSettings(p unsafe.Pointer, c int32) any {
	r := (*extractionshadow.ShadowSettings)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Enabled
	case 4:
		if r.ProviderID == nil {
			return nil
		}
		return string(*r.ProviderID)
	case 5:
		return int64(r.SamplePercent)
	case 6:
		return int64(r.DailyLimit)
	case 7:
		if r.UpdatedByID == nil {
			return nil
		}
		return string(*r.UpdatedByID)
	case 8:
		return r.Version
	case 9:
		return r.CreatedAt
	case 10:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateShadowSettings(ctx context.Context, p unsafe.Pointer) error {
	return (*extractionshadow.ShadowSettings)(p).BeforeCreate(ctx)
}

